'use strict';
var PDF_IMPORT={file:null,url:null,drafts:[],index:0,busy:false,result:null};
function pdfImportHTML(){return L`<section class="settings-card pdf-card"><span class="ai-eyebrow">PDF → 可编辑题目草稿</span><h3>直接导入 PDF</h3><p>文字版自动提取；扫描版尝试本机 OCR。先整理草稿、校对题目，再加入题库。PDF 不会自动发送给 AI，也不会保存到公共目录。</p><label class="upload-zone" for="pdf-file"><b id="pdf-filename">＋ 选择 PDF 文件</b><span>最多 25 MB · 每批最多 200 页 · OCR 每批最多 20 页</span></label><input id="pdf-file" type="file" accept="application/pdf,.pdf" hidden><div class="pdf-options"><label>起始页<input id="pdf-start" type="number" min="1" max="1000" value="1"></label><label>结束页<input id="pdf-end" type="number" min="1" max="1000" value="200"></label><label>题型<select id="pdf-kind"><option value="auto">自动判断</option>${Object.entries(TYPES).map(([k,t])=>`<option value="${k}">${t.name}</option>`).join('')}</select></label><label>拆题方式<select id="pdf-split"><option value="auto">按题组标题自动拆分</option><option value="page">每页一组</option><option value="whole">整个页码范围作为一组</option></select></label><label>扫描文字识别<select id="pdf-ocr"><option value="auto">文字不足时自动识别</option><option value="never">仅提取已有文字</option><option value="force">全部按扫描版识别</option></select></label></div><div class="import-buttons"><button class="btn" id="pdf-extract" disabled>识别并整理草稿 →</button><button class="btn secondary" id="pdf-resume" ${PDF_IMPORT.drafts.length?'':'hidden'}>继续整理草稿</button></div><p id="pdf-status" role="status">${location.protocol==='file:'?tr('请通过“开始练习.command”启动后使用 PDF 导入。'):tr('正在检查本机 PDF 识别服务…')}</p></section>`}
async function pdfService(){if(!['127.0.0.1','localhost'].includes(location.hostname))throw Error(tr('PDF 识别需要本机服务，请先双击“开始练习.command”。'));let r=await fetch('/api/pdf/status',{signal:AbortSignal.timeout(15000),cache:'no-store'});if(!r.ok)throw Error(tr('请重新启动本机练习平台以启用 PDF 导入。'));let status=await r.json();if(!status.available)throw Error(status.message);return status}
function pdfMessage(text){let target=$('#pdf-status');if(target)target.textContent=tr(text)}
function bindPDFImporter(){
 if(!$('#pdf-file'))return;
 pdfService().then(s=>{pdfMessage(tr(s.message)+(s.ocr?tr(' 本机支持扫描文字识别。'):tr(' 扫描版需要本机 OCR 工具。')));if($('#pdf-extract'))$('#pdf-extract').disabled=!PDF_IMPORT.file||PDF_IMPORT.busy}).catch(e=>pdfMessage(e.message));
 $('#pdf-file').onchange=e=>{let file=e.target.files[0];if(!file)return;if(file.size>25*1024*1024){pdfMessage(tr('PDF 最大支持 25 MB，请压缩或拆分文件。'));e.target.value='';return}PDF_IMPORT.file=file;$('#pdf-filename').textContent=file.name;$('#pdf-extract').disabled=PDF_IMPORT.busy;pdfMessage(tr('已选择文件。确认页码范围后开始识别。'));e.target.value=''};
 $('#pdf-ocr').onchange=()=>{if($('#pdf-ocr').value==='force')$('#pdf-end').value=Math.min(+$('#pdf-end').value,+$('#pdf-start').value+19)};
 $('#pdf-extract').onclick=extractPDF;$('#pdf-resume').onclick=showPDFEditor;
 if(PDF_IMPORT.file){$('#pdf-filename').textContent=PDF_IMPORT.file.name;$('#pdf-extract').disabled=PDF_IMPORT.busy}
}
async function extractPDF(){
 if(PDF_IMPORT.busy||!PDF_IMPORT.file)return;
 let start=+$('#pdf-start').value,end=+$('#pdf-end').value,mode=$('#pdf-ocr').value,kind=$('#pdf-kind').value,strategy=$('#pdf-split').value;
 if(!Number.isInteger(start)||!Number.isInteger(end)||start<1||end>1000||end<start||end-start>=200)return pdfMessage(tr('请选择连续 1–200 页，起始页不能晚于结束页。'));
 if(mode==='force'&&end-start>=20)return pdfMessage(tr('强制 OCR 每次最多 20 页，请缩小范围。'));
 let file=PDF_IMPORT.file;PDF_IMPORT.busy=true;$('#pdf-extract').disabled=true;
 try{
  let service=await pdfService();pdfMessage(tr('正在本机读取 PDF…扫描件识别可能需要几分钟，请保持页面打开。'));
  let r=await fetch(`/api/pdf/extract?start=${start}&end=${end}&ocr=${mode}`,{method:'POST',headers:{'Content-Type':'application/pdf','X-Practice-Token':service.requestToken},body:file,signal:AbortSignal.timeout(45000)});let job=await r.json();if(!r.ok)throw Error(job.error||tr('无法提交 PDF。'));
  let since=Date.now();
  while(['queued','running'].includes(job.status)){
   pdfMessage(job.status==='queued'?tr('PDF 正在排队…'):tr('正在本机提取文字并识别扫描页…不使用 AI 额度。'));
   await new Promise(resolve=>setTimeout(resolve,1500));if(Date.now()-since>450000)throw Error(tr('识别等待超时，请减少页码范围重试。'));
   r=await fetch('/api/pdf/jobs/'+encodeURIComponent(job.id),{cache:'no-store',signal:AbortSignal.timeout(15000)});job=await r.json();if(!r.ok)throw Error(job.error||tr('无法读取识别结果。'));
  }
  if(job.status!=='completed')throw Error(job.error||tr('PDF 识别未完成。'));
  // Discard the server copy as soon as the browser has received the result.
  await fetch('/api/pdf/jobs/'+encodeURIComponent(job.id),{method:'DELETE',headers:{'X-Practice-Token':service.requestToken}}).catch(()=>{});
  let drafts=PDFDrafts.parse(job.result.pages,kind,strategy);if(!drafts.length)throw Error(tr('没有提取到可用文字。扫描版请改为强制识别，或检查 OCR 依赖。'));if(drafts.length>500)throw Error(tr('识别出过多草稿，请缩小页码范围。'));
  if(PDF_IMPORT.url)URL.revokeObjectURL(PDF_IMPORT.url);PDF_IMPORT.url=URL.createObjectURL(file);PDF_IMPORT.drafts=drafts;PDF_IMPORT.index=0;PDF_IMPORT.result=job.result;
  if($('#pdf-resume'))$('#pdf-resume').hidden=false;pdfMessage(L`已整理 ${drafts.length} 组草稿，请核对后入库。`);showPDFEditor();
 }catch(e){pdfMessage(e.name==='TimeoutError'?tr('本机识别连接超时，请检查启动窗口或减少页码。'):e.message||tr('识别失败，请重试。'))}
 finally{PDF_IMPORT.busy=false;if($('#pdf-extract'))$('#pdf-extract').disabled=!PDF_IMPORT.file}
}
function pdfField(id,label,value='',rows=0){return `<label>${label}${rows?`<textarea id="${id}" rows="${rows}">${esc(value)}</textarea>`:`<input id="${id}" value="${esc(value)}">`}</label>`}
function pdfQuestionRows(q){return (q.questions||[]).map((x,i)=>L`<section class="pdf-question-row" data-pdf-row="${i}"><div class="ai-section-top"><b>小题 ${i+1}</b><button type="button" class="chip" data-pdf-remove="${i}">删除小题</button></div><label>题干或句子<textarea data-pdf-stem rows="3">${esc(x.stem)}</textarea></label>${['daily','academic'].includes(q.kind)?L`<label>作答方式<select data-pdf-answer-mode><option value="choice" ${x.options?.length?'selected':''}>四选一</option><option value="text" ${!x.options?.length?'selected':''}>文字作答</option></select></label>${x.options?.length?['A','B','C','D'].map(l=>L`<label>选项 ${l}<input data-pdf-option="${l}" value="${esc(x.options.find(o=>o.label===l)?.text||'')}"></label>`).join(''):''}<label>参考答案（可留空）<input data-pdf-answer value="${esc(x.answer||'')}" placeholder="${x.options?.length?tr('A、B、C 或 D'):tr('参考句子')}"></label>`:''}</section>`).join('')}
function showPDFEditor(){
 let state=PDF_IMPORT,d=state.drafts[state.index];if(!d)return;let q=d.question;
 modal(L`<div class="pdf-editor-top"><div><span class="ai-eyebrow">PDF IMPORT · REVIEW BEFORE PRACTICE</span><h2>把识别结果，整理成自己的题。</h2></div><button class="btn secondary" id="pdf-close">稍后继续</button></div><p>当前草稿 ${state.index+1} / ${state.drafts.length} · 来源第 ${d.pages.join('、')} 页 · 自动拆题不代表已核对正确。</p>${state.result?.warnings.length?L`<details class="pdf-warnings"><summary>文件识别提示（${state.result.warnings.length} 条）</summary>${state.result.warnings.map(s=>`<p>${esc(tr(s))}</p>`).join('')}</details>`:''}<div class="pdf-review-grid"><section class="pdf-source"><label>选择草稿<select id="pdf-draft-index">${state.drafts.map((x,i)=>`<option value="${i}" ${state.index===i?'selected':''}>${x.selected?'✓':'○'} ${i+1}. ${esc(x.question.title)}</option>`).join('')}</select></label><div class="ai-section-top"><h3>提取原文</h3><a id="pdf-open-original" href="${state.url}#page=${d.pages[0]}" target="_blank" rel="noopener">查看 PDF ↗</a></div><p>原文只用于对照；右侧改动不会修改 PDF。</p><pre>${esc(d.raw)}</pre><button class="btn secondary" id="pdf-copy-source">复制这组原文</button></section><section class="pdf-draft"><label class="rights-check"><input id="pdf-include" type="checkbox" ${d.selected?'checked':''}> 将这组草稿加入题库</label>${d.warnings.length?`<div class="pdf-warnings">${d.warnings.map(s=>`<p>${esc(tr(s))}</p>`).join('')}</div>`:''}<label>题型<select id="pdf-edit-kind">${Object.entries(TYPES).map(([k,t])=>`<option value="${k}" ${q.kind===k?'selected':''}>${t.name}</option>`).join('')}</select></label>${pdfField('pdf-edit-title',tr('标题'),q.title)}${pdfField('pdf-edit-seconds',tr('时限（秒；口语为每小题）'),q.seconds)}${['email','discussion'].includes(q.kind)?pdfField('pdf-edit-prompt',tr('完整题目要求与讨论材料'),q.prompt,10)+(q.kind==='email'?pdfField('pdf-edit-to',tr('收件人（可选）'),q.to)+pdfField('pdf-edit-subject',tr('主题（可选）'),q.subject):''):q.kind==='fill'?pdfField('pdf-edit-passage',tr('填词段落（每个下划线表示一个字母）'),q.passage,9)+pdfField('pdf-edit-answers',tr('完整单词答案（英文逗号分隔，可留空）'),q.answers.join(', ')):(['daily','academic'].includes(q.kind)?pdfField('pdf-edit-passage',tr('阅读材料'),q.passage,8):'')+pdfQuestionRows(q)+L`<button type="button" class="btn secondary" id="pdf-add-question">＋ 添加小题</button>`}</section></div><p id="pdf-review-error" class="form-error" role="alert"></p><div class="modal-actions pdf-review-actions"><button class="btn secondary" id="pdf-previous" ${state.index?'':'disabled'}>← 上一组</button><button class="btn secondary" id="pdf-next" ${state.index===state.drafts.length-1?'disabled':''}>下一组 →</button><button class="btn" id="pdf-preview-selected">预览选中的题目 →</button></div>`);
 $('.modal').classList.add('pdf-review-modal');bindPDFEditor();
}
function capturePDFDraft(){let d=PDF_IMPORT.drafts[PDF_IMPORT.index];if(!d||!$('#pdf-edit-title'))return;let q=d.question;d.selected=$('#pdf-include').checked;q.title=$('#pdf-edit-title').value;q.seconds=Number($('#pdf-edit-seconds').value);if(['email','discussion'].includes(q.kind)){q.prompt=$('#pdf-edit-prompt').value;q.to=$('#pdf-edit-to')?.value||'';q.subject=$('#pdf-edit-subject')?.value||''}else if(q.kind==='fill'){q.passage=$('#pdf-edit-passage').value;q.answers=$('#pdf-edit-answers').value.trim()?$('#pdf-edit-answers').value.split(',').map(x=>x.trim()):[]}else{if(['daily','academic'].includes(q.kind))q.passage=$('#pdf-edit-passage').value;q.questions=$$('[data-pdf-row]').map(row=>{let x={stem:row.querySelector('[data-pdf-stem]').value};if(['daily','academic'].includes(q.kind)){x.options=row.querySelector('[data-pdf-answer-mode]').value==='choice'?['A','B','C','D'].map(l=>({label:l,text:row.querySelector(`[data-pdf-option="${l}"]`)?.value||''})):[];x.answer=row.querySelector('[data-pdf-answer]').value.trim()||null}return x})}}
function bindPDFEditor(){
 $('#pdf-close').onclick=()=>{capturePDFDraft();closeModal()};$('#pdf-draft-index').onchange=e=>{capturePDFDraft();PDF_IMPORT.index=+e.target.value;showPDFEditor()};
 $('#pdf-previous').onclick=()=>{capturePDFDraft();PDF_IMPORT.index--;showPDFEditor()};$('#pdf-next').onclick=()=>{capturePDFDraft();PDF_IMPORT.index++;showPDFEditor()};
 $('#pdf-edit-kind').onchange=e=>{let kind=e.target.value;capturePDFDraft();let d=PDF_IMPORT.drafts[PDF_IMPORT.index],fresh=PDFDrafts.parse([{number:d.pages[0],text:d.raw}],kind,'whole')[0];fresh.question.id=d.question.id;fresh.question.title=d.question.title;fresh.selected=d.selected;fresh.pages=d.pages;PDF_IMPORT.drafts[PDF_IMPORT.index]=fresh;showPDFEditor()};
 if($('#pdf-add-question'))$('#pdf-add-question').onclick=()=>{capturePDFDraft();let q=PDF_IMPORT.drafts[PDF_IMPORT.index].question;if(q.questions.length>=50)return toast(tr('每组最多 50 小题'));q.questions.push({stem:'',...(['daily','academic'].includes(q.kind)?{options:['A','B','C','D'].map(label=>({label,text:''})),answer:null}:{})});showPDFEditor()};
 $$('[data-pdf-remove]').forEach(b=>b.onclick=()=>{capturePDFDraft();let q=PDF_IMPORT.drafts[PDF_IMPORT.index].question;if(q.questions.length===1)return toast(tr('至少保留一道小题；不需要的题组可以取消勾选。'));q.questions.splice(+b.dataset.pdfRemove,1);showPDFEditor()});
 $$('[data-pdf-answer-mode]').forEach(select=>select.onchange=()=>{capturePDFDraft();showPDFEditor()});
 $('#pdf-copy-source').onclick=async()=>{try{await navigator.clipboard.writeText(PDF_IMPORT.drafts[PDF_IMPORT.index].raw);toast(tr('原文已复制'))}catch{toast(tr('请在左侧选择原文复制'))}};
 $('#pdf-preview-selected').onclick=()=>{capturePDFDraft();try{let selected=PDF_IMPORT.drafts.filter(d=>d.selected).map(d=>d.question);if(!selected.length)throw Error(tr('请至少勾选一组草稿。'));previewQuestions(selected);$('#cancel-questions').textContent=tr('返回校对');$('#cancel-questions').onclick=showPDFEditor}catch(e){$('#pdf-review-error').textContent=e.message}};
}
window.addEventListener('pagehide',()=>{if(PDF_IMPORT.url)URL.revokeObjectURL(PDF_IMPORT.url)});
